ALTER TABLE users ADD CONSTRAINT users_nickname_len CHECK (length(nickname) < 40) NOT VALID;

-- Validate constraint (scans table but allows concurrent reads/writes)
ALTER TABLE users VALIDATE CONSTRAINT users_nickname_len;",
